def parse_json(json_str):
    def parse_value(value_str):
        value_str = value_str.strip()
        if value_str == 'true':
            return True
        elif value_str == 'false':
            return False
        elif value_str == 'null':
            return None
        elif value_str[0] == '"':
            return value_str[1:-1].replace('\\"', '"').replace('\\n', '\n').replace('\\t', '\t').replace('\\b', '\b').replace('\\f', '\f').replace('\\r', '\r')
        elif value_str[0] == '[':
            return parse_array(value_str)
        elif value_str[0] == '{':
            return parse_object(value_str)
        else:
            try:
                return int(value_str)
            except ValueError:
                try:
                    return float(value_str)
                except ValueError:
                    raise ValueError(f"Invalid JSON value: {value_str}")

    def parse_array(array_str):
        array_str = array_str.strip()[1:-1].strip()
        if not array_str:
            return []
        elements = array_str.split(',')
        return [parse_value(element.strip()) for element in elements]

    def parse_object(object_str):
        object_str = object_str.strip()[1:-1].strip()
        if not object_str:
            return {}
        pairs = object_str.split(',')
        return {pair.split(':')[0].strip(): parse_value(pair.split(':')[1].strip()) for pair in pairs}

    try:
        return parse_value(json_str)
    except (SyntaxError, ValueError) as e:
        raise ValueError(f"Invalid JSON: {e}")

